ALTER TABLE "event_settings" ADD COLUMN "location" text DEFAULT '' NOT NULL;--> statement-breakpoint
ALTER TABLE "event_settings" ADD COLUMN "starts_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "event_settings" ADD COLUMN "faqs" jsonb DEFAULT '[]'::jsonb NOT NULL;--> statement-breakpoint
-- Existing events start with the default FAQ; new ones get it from seedDefaults.
UPDATE "event_settings" SET "faqs" = $faqs$[{"question":"Is the event free?","answer":"Yes, since most partygoers take part in the challenges. If you’re not entering a friendly competition, we encourage you to donate to the pizza fund."},{"question":"Can I bring my kids?","answer":"No, this is a 21-and-up party. All the other events around the holidays will include our children."},{"question":"When should I show up?","answer":"If you’re entering a challenge, please try to arrive within the first hour of the event."},{"question":"When are the winners announced?","answer":"Around 8–9 pm."},{"question":"Can I bring something to share but not enter it in the competitions?","answer":"Of course! We’d love anything you’d like to share with the PDXmas family."}]$faqs$::jsonb WHERE "faqs" = '[]'::jsonb;
